class Processor
  Seen = Struct.new(:result, :recorded_at)

  attr_reader :effects

  def initialize(window)
    @window = window
    @effects = []
    @seen = {}
  end

  def process(key, payload, now)
    cached = @seen[key]
    if cached && now - cached.recorded_at < @window
      return cached.result
    end
    @effects << [key, payload]
    result = { key: key, payload: payload, processed_at: now }
    @seen[key] = Seen.new(result, now)
    result
  end
end

