class Processor
  attr_reader :effects

  def initialize(window)
    @window = window
    @effects = []
    @seen = {}
  end

  def process(key, payload, now)
    return @seen[key] if @seen.key?(key)
    @effects << [key, payload]
    result = { key: key, payload: payload, processed_at: now }
    @seen[key] = result
    result
  end
end
